android.extraProguardRules:
# O expo-notifications guarda os lembretes agendados nas SharedPreferences
# via serializacao Java. writeObject/readObject so sao chamados por reflexao,
# entao o R8 os remove e a serializacao default explode em
# NotSerializableException: org.json.JSONObject (campo mBody de
# NotificationContent). Sem estas regras, nenhum lembrete e agendado em
# release. O expo-notifications nao traz regras proprias.
-keepnames class org.json.JSONObject
-keep class expo.modules.notifications.** { *; }
-keepclassmembers class * implements java.io.Serializable {
    static final long serialVersionUID;
    private static final java.io.ObjectStreamField[] serialPersistentFields;
    private void writeObject(java.io.ObjectOutputStream);
    private void readObject(java.io.ObjectInputStream);
    java.lang.Object writeReplace();
    java.lang.Object readResolve();
}
